-- the ranks of the zones, as the game orders its sets
Azerloot_Loot.ranks = { "Common", "Uncommon", "Rare", "Epic", "PvP", "Legendary" }

-- The PvP set wears the hero's own faction: its names and pictures turn to the Horde
-- ones for a Horde hero. True when it changed anything.
function Azerloot_Loot.UseFaction(faction)
  local want = (faction == "Horde") and "Horde" or "Alliance"
  if Azerloot_Loot.faction == want then return false end
  for cls, zones in pairs(Azerloot_Loot.drops) do
    for zi = 1, table.getn(zones) do
      for bi = 1, table.getn(zones[zi]) do
        local items = zones[zi][bi]
        for k = 1, table.getn(items) do
          local it = items[k]
          if it.horde then
            it.alliance = it.alliance or it.name
            it.allianceIcon = it.allianceIcon or it.icon
            if want == "Horde" then it.name, it.icon = it.horde, it.hordeIcon
            else it.name, it.icon = it.alliance, it.allianceIcon end
          end
        end
      end
    end
  end
  Azerloot_Loot.faction = want
  return true
end
